using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.WildThyme;

/// <summary>
/// Wild thyme, low mats of tiny leaves and purple flowers on the cooled lava of the Ashlands; the Icelanders call it
/// blood-berg. Model: generated by AssetSource/Tools/make_forage_models.py. Smoke Puffs picked in the Ashlands can also
/// give it.
/// </summary>
public class WildThyme : ForageableBase
{
    /// <summary>
    /// Prefab name of the wild thyme item.
    /// </summary>
    public const string PrefabName = "WhiteHiltWildThyme";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Wild Thyme";

    /// <inheritdoc/>
    protected override string Description => "Tiny fragrant leaves and purple flowers from a mat on the cooled lava. It seasons meat and makes a warming tea.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 35f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_SmokePuff";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.2f;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "thyme", 0.09f);
    }
}
